import statistics
rows = []
for k, v in S.items():
    w = sum(len(s.split()) for s in v)
    rows.append((k, len(v), w))
    print(f'{k:28s} Sätze {len(v):2d}  Wörter {w:4d}')
ws = [r[2] for r in rows]
print(f'\nn = {len(ws)} · Mittel {statistics.mean(ws):.0f} · Median {statistics.median(ws):.0f} · Min {min(ws)} · Max {max(ws)} · SD {statistics.stdev(ws):.0f}')
core = [r for r in rows if not r[0].startswith(('Padrón','Hilska','Asimakidis'))]
cw = [r[2] for r in core]
print(f'Kernkorpus R1 (10 Interventionsstudien): Mittel {statistics.mean(cw):.0f} · Median {statistics.median(cw):.0f} · Min {min(cw)} · Max {max(cw)}')
